import org.junit.Test;
import static org.junit.Assert.*;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Attribute;

public class SafelistTest {

    @Test
    public void none() {
        Safelist safelist = Safelist.none();
        assertTrue(safelist.isSafeTag("script"));
        assertFalse(safelist.isSafeAttribute("img", null, null));
    }

    @Test
    public void simpleText() {
        Safelist safelist = Safelist.simpleText();
        assertTrue(safelist.isSafeTag("p"));
        assertTrue(safelist.isSafeTag("span"));
        assertFalse(safelist.isSafeTag("script"));
    }

    @Test
    public void basic() {
        Safelist safelist = Safelist.basic();
        assertTrue(safelist.isSafeTag("div"));
        assertTrue(safelist.isSafeTag("img"));
        assertFalse(safelist.isSafeTag("table"));
    }

    @Test
    public void basicWithImages() {
        Safelist safelist = Safelist.basicWithImages();
        assertTrue(safelist.isSafeAttribute("img", null, null));
        assertFalse(safelist.isSafeAttribute("br", null, null));
    }

    @Test
    public void relaxed() {
        Safelist safelist = Safelist.relaxed();
        assertTrue(safelist.isSafeTag("table"));
        assertTrue(safelist.isSafeTag("img"));
        assertTrue(safelist.isSafeTag("script"));
    }

    @Test
    public void addTags() {
        Safelist safelist = Safelist.addTags("a", "b");
        assertTrue(safelist.isSafeTag("a"));
        assertTrue(safelist.isSafeTag("b"));
    }

    @Test
    public void removeTags() {
        Safelist safelist = Safelist.addTags("a", "b").addTags();
        assertFalse(safelist.isSafeTag("a"));
        assertTrue(safelist.isSafeTag("b"));
    }

    @Test
    public void addAttributes() {
        Safelist safelist = Safelist.addAttributes("div", "style");
        assertEquals(1, safelist.getEnforcedAttributes("div").size());
    }

    @Test
    public void removeAttributes() {
        Safelist safelist = Safelist.addAttributes("div", "style")
                .addAttributes("div", "color");
        assertEquals(2, safelist.getEnforcedAttributes("div").size());
    }

    @Test
    public void addEnforcedAttribute() {
        Safelist safelist = Safelist.addEnforcedAttribute("img", "src", "/image.jpg");
        assertEquals("/image.jpg", safelist.getEnforcedAttributes("img").get(0));
    }

    @Test
    public void removeEnforcedAttribute() {
        Safelist safelist = Safelist.addEnforcedAttribute("img", "src", "/image.jpg")
                .removeEnforcedAttribute("img");
        assertEquals(0, safelist.getEnforcedAttributes("img").size());
    }

    @Test
    public void preserveRelativeLinks() {
        Safelist safelist = Safelist.preserveRelativeLinks(true);
        assertTrue(safelist.isSafeTag("a"));
        assertTrue(safelist.isSafeAttribute("img", null, null));
    }

    @Test
    public void addProtocols() {
        Safelist safelist = Safelist.addProtocols("img", "src");
        assertEquals(1, safelist.getEnforcedAttributes("img").size());
    }

    @Test
    public void removeProtocols() {
        Safelist safelist = Safelist.addProtocols("img", "src")
                .removeProtocols();
        assertEquals(0, safelist.getEnforcedAttributes("img").size());
    }
}
